INNER JOIN project p
    ON p.id = t.project_id
SET t.assignee_user_id = NULL,
    t.assigned_by_user_id = #{assignedByUserId},
    t.assigned_at = #{assignedAt}
WHERE p.team_id = #{teamId}
  AND t.assignee_user_id = #{memberUserId}
  AND t.status = 0


        AND t.id IN

